class Sku:
    def __init__(self, code: str, region: str, stock: int):
        self.code = code
        self.region = region
        self.stock = stock

    def __eq__(self, other):
        if not isinstance(other, Sku):
            return False
        return self.code == other.code and self.region == other.region

    def __hash__(self):
        return hash((self.code, self.region, self.stock))

    def __repr__(self):
        return f"Sku(code={self.code!r}, region={self.region!r})"


def dedupe(skus):
    seen = set()
    out = []
    for s in skus:
        if s not in seen:
            seen.add(s)
            out.append(s)
    return out

